from app import Telemetry

t = Telemetry(iter(range(100)).__next__)
t.start("a"); t.finish("a", error="x")
t.start("b", service="api"); t.finish("b", service="api")
t.start("c", service="api")
t.start("d", service="api", labels=(("k","v"),)); t.finish("d", service="api", error=0)
assert t.span_duration_stats(service="api")["count"] == 2
assert t.span_duration_stats(service="missing") is None
assert t.span_duration_stats(labels=())["count"] == 1
assert t.span_duration_stats(labels=(("k","v"),))["count"] == 1
assert t.span_duration_stats(service="api", status="error")["count"] == 1
t3 = Telemetry(); t3.start("o")
assert t3.span_duration_stats() is None

for bad in ("open", "", "CLOSED", None, 0, b"closed", ["closed"], "done"):
    try: t.span_duration_stats(status=bad)
    except ValueError: pass
    else: raise AssertionError("status %r" % (bad,))
for bad in (1, b"api", ["api"]):
    try: t.span_duration_stats(service=bad)
    except ValueError: pass
    else: raise AssertionError("service %r" % (bad,))
try: t.span_duration_stats(labels=(("k",1),("k",2)))
except ValueError: pass
else: raise AssertionError("dup labels")
try: t.span_duration_stats(service="zzz", labels="bad")
except ValueError: pass
else: raise AssertionError("labels validation order")

def boom(): raise AssertionError("clock read")
t.clock = boom
t.span_duration_stats(); t.span_duration_stats(status="error")
try: t.span_duration_stats(status="open")
except ValueError: pass

t4 = Telemetry(); t4.start("s"); t4.finish("s")
t4.spans[("", "s")]["end"] = "2020"
before = t4.snapshot()
try: t4.span_duration_stats()
except ValueError: pass
else: raise AssertionError("string end")
assert t4.snapshot() == before

t5 = Telemetry()
t5.spans[("", "x")] = {"parent": None, "start": 0, "end": float("nan"), "error": None, "labels": ()}
try: t5.span_duration_stats()
except ValueError: pass
else: raise AssertionError("nan end")
t5.spans[("", "x")]["end"] = 1.0; t5.spans[("", "x")]["start"] = object()
try: t5.span_duration_stats()
except ValueError: pass
else: raise AssertionError("object start")

t6 = Telemetry(iter(range(100)).__next__)
t6.start("good"); t6.finish("good")
t6.spans[("", "bad")] = {"parent": None, "start": 0, "end": "nope", "error": None, "labels": ()}
try: t6.span_duration_stats()
except ValueError: pass
else: raise AssertionError("mixed bad")

t7 = Telemetry()
t7.spans[("", "o")] = {"parent": None, "start": "nope", "end": None, "error": None, "labels": ()}
assert t7.span_duration_stats() is None

s1 = t.span_duration_stats(); s2 = t.span_duration_stats()
assert s1 is not s2 and s1["values"] is not s2["values"]
s1["values"].append(999); s1["count"] = 0
assert t.span_duration_stats()["count"] == 3

assert set(t.snapshot()) == {"counters","samples","spans"}
assert all(type(v) is float for v in t.span_duration_stats()["values"])
assert type(t.span_duration_stats()["sum"]) is float

t8 = Telemetry()
t8.spans[("", "n")] = {"parent": None, "start": "1", "end": "4.5", "error": None, "labels": ()}
assert t8.span_duration_stats()["values"] == [3.5]

t9 = Telemetry()
t9.spans[("", "e")] = {"parent": None, "start": 0, "end": 1, "error": 0, "labels": ()}
assert t9.span_duration_stats(status="error")["count"] == 1
assert t9.span_duration_stats(status="closed")["count"] == 1

# huge int overflow -> ValueError (matches sample rule)
t10 = Telemetry()
t10.spans[("", "h")] = {"parent": None, "start": 0, "end": 10**400, "error": None, "labels": ()}
try: t10.span_duration_stats()
except ValueError: pass
else: raise AssertionError("overflow")

# works after restore / merge / from_snapshot
base = Telemetry(iter(range(100)).__next__)
base.start("r"); base.finish("r")
restored = Telemetry.restore(base.json())
assert restored.span_duration_stats()["values"] == [1.0]
m = Telemetry(); m.merge_snapshot(base.snapshot())
assert m.span_duration_stats()["values"] == [1.0]
assert Telemetry.from_snapshot(base.snapshot()).span_duration_stats()["values"] == [1.0]

# open spans still queryable; error/exception object preservation unaffected
assert [e["span"] for e in t.query("open")] == ["c"]

print("ALL SCRATCH CHECKS PASSED")
